    long long n;
    long long k;
    cin >> n >> k;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    deque<long long> window;
    long long total = 0;
    for (int i = 0; i < n; i++) {
        window.push_back(a[i]);
        total += a[i];
        if ((long long) window.size() > k) {
            total -= window.front();
            window.pop_front();
        }
        cout << total << (i + 1 < n ? " " : "\n");
    }

    return 0;
}

